div.script:
    function checkInvalidError() {

        var isInvalid = "";
        if ('' != null)
            isInvalid = '';

        if (isInvalid != "") {
            $("#invalidData").removeClass('hidden');
            $("#invalidData").html('' + isInvalid + '');
            $("#ShowData").removeClass("hideDiv");
            $("#UserId").focus();
        }

    }

    $(document).on("keypress", ".alphanumeric input:text", function (e) {
        var k = e.which;
        if ((k >= 65 && k <= 90) || (k >= 97 && k <= 122) || (k >= 48 && k <= 57) ||(k==95) ){ return true; }
        else { e.preventDefault() }
    });

    $(document).ready(function () {
        
        checkInvalidError();

        $('#UserId').focus();

        $(document).on("keypress", "#UserId", function (e) {
            var k = e.which;
            if (k == 13) {
                LoginFunction();
            }

        });
        if (!window.location.origin) {
            window.location.origin = window.location.protocol + "//"
              + window.location.hostname
              + (window.location.port ? ':' + window.location.port : '');
        }
        $("#hdnhost").val(window.location.origin + "/");
        $("#imageMaps").attr("href", window.location.origin + "/" + "home/index");


        var x1 = 1;
        var y1 = 1;
        var x2 = 200;
        var y2 = 100;
        x2 = $(window).width() / 6;
        y2 = $(window).width() / 12;
        $("#imageMaps").attr("coords", '' + x1 + ',' + y1 + ',' + x2 + ',' + y2 + '');

        // bind a click event to the 'skip' link
        $(".skip").click(function (event) {
            // strip the leading hash and declare
            // the content we're skipping to
            var skipTo = "#" + this.href.split('#')[1];
            //alert(skipTo);
            // Setting 'tabindex' to -1 takes an element out of normal
            // tab flow but allows it to be focused via javascript
            $(skipTo).attr('tabindex', -1).on('blur focusout', function () {

                // when focus leaves this element,
                // remove the tabindex attribute
                $(this).removeAttr('tabindex');

            }).focus(); // focus on the content container
        });
    });

    function LoginFunction() {
        //event.preventDefault();
        var maxAttempt = 2;
        var check=false;

        if(check)
            window.location='/Error/ApplicationAccessError';
        else{
            var userId = $("#UserId").val();
            if (userId != null && userId != "") {
                $("#spinnerPopup").modal('show');
                $.ajax({
                    url: "/LogOn/SaveUserId",
                    data: { UserId: userId },
                    type: "POST",
                    success: function (data) {

                        if(data=="")
                            window.location='/Home/Index';
                        else if(data == "3"){
                            window.location='/LogOn/ChangePassword';
                        }else{
                            window.location = '/Logon/Index';
                        }
                    },
                    error: function (response) {
                        alert("error : " + response.statusText);
                    }
                });
            }
            else {
                $("#invalidData").removeClass('hidden');
                $("#invalidData").html('Please enter your User ID'); //return to home page incase of issue
                $("#UserId").focus();
            }
        }
    }

    $(window).resize(function () {
        var x1 = 1;
        var y1 = 1;
        var x2 = 200;
        var y2 = 100;
        x2 = $(window).width() / 6;
        y2 = $(window).width() / 12;
        $("#imageMaps").attr("coords", '' + x1 + ',' + y1 + ',' + x2 + ',' + y2 + '');
    });

    function show() {
        $("#ShowData").toggleClass("hideDiv");
        $("#UserId").focus();
    }

    function GoToHome(event)
    {
        //debugger;
        if (event.which === 13) {
            //event.stopPropagation;
            window.open('/home/index', '_self');
        }
        return true;
    }

    function ShowLoadingImage() {
        //debugger;
        $("#spinnerPopup").modal('show');
        return true;
    }

