    };

    function isExternalLink(target) {
        return true;
    }

    function moreNews() {

        // fix of Client DOM Open Redirect
        try {
            var surl = window.location.origin + $("#hdnvd").val() + "NewsAndEventDetails/Index";
            if (validateURL(surl))
                window.open(surl, "_self");
            else {
                throw new InvalidURLException();
            }
        } catch (e) {
            if (e instanceof InvalidURLException)
                alert(e.message);
        }
    }


    function InvalidURLException() {
        this.message = "An attempt was made to open a webpage of foreign domain. No allowed.";
        this.toString = function () {
            return this.message
        };
    }

    function validateURL(surl) {
        var url = parseURL(surl);
        var urlHostname = url.hostname.trim();

        if (urlHostname == '') {
            return true;
        }
        else {
            if (urlHostname.toUpperCase() == location.hostname.trim().toUpperCase()) {
                return true;
            }
            else
                return false;
        }
    }

    function parseURL(url) {
        var a = document.createElement('a');
        a.href = url;
        return {
            source: url,
            protocol: a.protocol.replace(':', ''),
            hostname: a.hostname,
            host: a.host,
            port: a.port,
            query: a.search,
            params: (function () {
                var ret = {},
                    seg = a.search.replace(/^\?/, '').split('&'),
                    len = seg.length, i = 0, s;
                for (; i < len; i++) {
                    if (!seg[i]) { continue; }
                    s = seg[i].split('=');
                    ret[s[0]] = s[1];
                }
                return ret;
            })(),
            file: (a.pathname.match(/\/([^\/?#]+)$/i) || [, ''])[1],
            hash: a.hash.replace('#', ''),
            path: a.pathname.replace(/^([^\/])/, '/$1'),
            relative: (a.href.match(/tps?:\/\/[^\/]+(.+)/) || [, ''])[1],
            segments: a.pathname.replace(/^\//, '').split('/')
        };
    }

    function newsDetail(newsId, subtype) {
        $("#news_id").val(newsId);
        $("#news_subtype").val(subtype);
        $("#newsfrm").submit();

    }
    function NavigateFHRole() {
        window.open($("#hdnhost").val() + 'LocateProvider/FirstHealthRole', "_self");
    }

