    function Navigate(linkId, linkType, linkUrl, pageId, title) {
        if (linkType == "") {

        }
        else if (linkType == "_blank") {
            var result = isExternalLink(linkUrl);
            if (result) {
                window.open(linkUrl, "_new");
            }
        }
        else if (linkType == "_self") {
            window.open($("#hdnhost").val() + "Home/Index/" + pageId, "_self");
        }
        else if (linkType == "popup") {
            $("#RightpartialViewContainerDiv").html($("#" + linkId).html());
            $('.modal-title-custom').html(title);
            $('#RightModal').modal({
                backdrop: 'static'
            });

            $('#RightpartialViewContainerDiv').find('#1').focus();

            var AnchorCount = $('#RightpartialViewContainerDiv').find('a').each(function () {
            }).length;
            var lastElement = $("#RightpartialViewContainerDiv").find('#' + AnchorCount);
            $(lastElement).on('keydown', function (e) {
                if ((e.which === 9 && !e.shiftKey)) {
                    e.preventDefault();
                    $(".modal-content").find(".Modalbox-close").focus();
                }
            });

            $(".modal-content").find(".Modalbox-close").on('keydown', function (e) {
                if ((e.which === 9 && !e.shiftKey)) {
                    e.preventDefault();
                    $('#RightpartialViewContainerDiv').find('#1').focus();
                }

            });
        }
        else if (linkType == "pdf" || linkType == "xlsx") {
            window.open($("#hdnhost").val() + "Home/RetrieveFile?linkId=" + linkId, "_blank");
        }
        else if (linkType == "_locate") {
            window.open($("#hdnhost").val() + linkUrl, "_self");
        }
        else if (linkType == "_assist") {
            window.open($("#hdnhost").val() + "QPAAssist/ClaimSearch", "_self");
        }
    };

    var CharREmaining = ' characters remaining';
    $(document).ready(function () {
        var characters = 1000;
        $("#Comments_feedback_mob").attr('maxlength', '1000');
        $("#JustificationComment").attr('maxlength', '1000');
        var rem_chars = 1000;
        $("#Feedback_comment_chars").html(rem_chars + " characters remaining");
        $("#jusification_comment_chars").html(rem_chars + " characters remaining");

        $("#Comments_feedback_mob").keyup(function () {

            var text_len = $("#Comments_feedback_mob").val().length;
            rem_chars = 1000 - text_len;
            if (text_len > characters) {
                $("#Comments_feedback_mob").val($("#Comments_feedback_mob").val().substr(0, characters));
            }
            if (rem_chars <= 0)
            { rem_chars = 0; }
            $("#Feedback_comment_chars").html(rem_chars + " characters remaining");
        });

        $("#JustificationComment").keyup(function () {

            var text_len = $("#JustificationComment").val().length;
            rem_chars = 1000 - text_len;
            if (text_len > characters) {
                $("#JustificationComment").val($("#JustificationComment").val().substr(0, characters));
            }
            if (rem_chars <= 0)
            { rem_chars = 0; }

            $("#jusification_comment_chars").html(rem_chars + " characters remaining");
        });
    });

    function SaveFeedbackDetails() {

        var model = new Object();
        model.Comments = $("#Comments_feedback_mob").val();
        if (!(model.Comments === undefined))
            model.Comments = model.Comments.trim();
        model.ContentRating = $('input[name=ContentRating]:checked').val();
        model.DesignRating = $('input[name=DesignRating]:checked').val();
        model.EaseOfUserRating = $('input[name=EaseOfUserRating]:checked').val();
        model.OverallRating = $('input[name=OverallRating]:checked').val();
        var validInfo = $('input[name=IsValidInfo]:checked').val();
        if (validInfo == "Yes")
            model.IsValidInfo = true;
        else if (validInfo == "No")
            model.IsValidInfo = false;
        model.JustificationComment = $("#JustificationComment").val();
        if (!(model.JustificationComment === undefined))
            model.JustificationComment = model.JustificationComment.trim();
        if (model.OverallRating === undefined) {
            $('#success_message_feedback').hide();
            $('#Error_message').show();
        }
        else {
            var json = JSON.stringify(model);
            var forgeryId = $("#forgeryToken").val();
            var Url = $("#hdnhost").val() + 'Home/FeedbackDetails'
            $.ajax({
                type: 'POST',
                url: Url,
                contentType: "application/json; charset=utf-8",
                datatype: 'json',
                data: json,
                headers: {
                    'VerificationToken': forgeryId
                },
                success: function (result) {
                    $('#Error_message').hide();
                    $('#Comments_feedback_mob').val("");
                    $('#JustificationComment').val("");
                    $('input[name="ContentRating"]').attr('checked', false);
                    $('input[name="DesignRating"]').attr('checked', false);
                    $('input[name="EaseOfUserRating"]').attr('checked', false);
                    $('input[name="OverallRating"]').attr('checked', false);
                    $('input[name="IsValidInfo"]').attr('checked', false);
                    $("#Feedback_comment_chars").html("1000 characters remaining");

                    $('#success_message_feedback').slideDown({ opacity: "show" }, "slow")
                    setTimeout(function () {
                        $('#success_message_feedback').fadeOut(1500);
                    }, 5000);
                },

            });
        }
    };

